import React, { useRef } from 'react';
import { useIntl } from 'react-intl';

import { ZoomInIcon, ZoomOutIcon } from '@dynatrace/strato-icons';

import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { getKeyShortcutByAgent } from '../../../core/functions/get-key-shortcut-by-agent.js';
import {
  isZoomIn,
  isZoomInWheel,
  isZoomOut,
  isZoomOutWheel,
} from '../../../core/functions/toolbarEvents.js';
import { useA11yToolbarTabIndex } from '../../../core/hooks/useA11yToolbarTabIndex.js';
import { useOverlaysEvents } from '../../../core/hooks/useOverlaysEvents.js';
import { useToolbarEvent } from '../../../core/hooks/useToolbarEvent.js';
import { ZoomInZoomOut } from '../../../core/types/zoom.js';
import { useSetState, useZoomState } from '../../hooks/store/selectors.js';
import { useSetResetOverlaysState } from '../../hooks/store/state-setters.js';
import { useHistogramInteractions } from '../../hooks/useHistogramInteractions.js';
import { useHistogramXScale } from '../../hooks/useHistogramXScale.js';
import { HISTOGRAM_MESSAGES } from '../../messages/tooltip-text.js';
import { getHistogramZoomStep } from '../../utils/zoom.js';

export const ZoomInOutButtons = () => {
  const zoomInButtonRef = useRef<HTMLButtonElement>();
  const zoomOutButtonRef = useRef<HTMLButtonElement>();
  const setState = useSetState();
  const tabIndexIn = useA11yToolbarTabIndex('zoom-in');
  const tabIndexOut = useA11yToolbarTabIndex('zoom-out');
  const { zoomInEnabled, zoomOutEnabled } = useZoomState();
  const { initialXScale, xScale } = useHistogramXScale();
  const { onZoomChange } = useHistogramInteractions();
  const { mousePosition, overlayRef } = useOverlaysEvents();
  const intl = useIntl();
  const { zoom } = useHistogramInteractions();
  const isZoomEnabled = zoom?.enabled;
  const setResetOverlaysState = useSetResetOverlaysState();

  const handleZoomKeyboardMode = (
    event: KeyboardEvent,
    zoomBehavior: ZoomInZoomOut,
  ) => {
    if (event.code === 'Enter') {
      handleZoom(zoomBehavior);
    }
  };

  const handleZoom = (zoomState: ZoomInZoomOut, zoomFromCursor = false) => {
    const cursorXPoint = zoomFromCursor
      ? mousePosition && xScale.invert(mousePosition.x)
      : undefined;

    const { newDomain, isMinZoom, isMaxZoom } = getHistogramZoomStep(
      initialXScale.domain(),
      xScale.domain(),
      zoomState,
      cursorXPoint,
    );

    const [start, end] = newDomain ?? initialXScale.domain();
    onZoomChange && onZoomChange(start, end, zoomState);

    setResetOverlaysState();
    setState((prevState) => ({
      ...prevState,
      currentDomain: newDomain,
      zoom: {
        ...prevState.zoom,
        zoomInEnabled: !isMaxZoom,
        zoomOutEnabled: !isMinZoom,
      },
    }));
  };

  function zoomInEvent() {
    handleZoom('zoom-in', true);
    zoomInButtonRef.current?.focus();
  }

  useToolbarEvent<KeyboardEvent>(
    'keydown',
    zoomInEvent,
    isZoomIn,
    isZoomEnabled && zoomInEnabled,
    overlayRef?.current as HTMLDivElement,
  );

  useToolbarEvent<WheelEvent>(
    'wheel',
    () => handleZoom('zoom-in', true),
    isZoomInWheel,
    isZoomEnabled && zoomInEnabled,
    overlayRef?.current as HTMLDivElement,
  );

  function zoomOutEvent() {
    handleZoom('zoom-out', true);
    zoomOutButtonRef.current?.focus();
  }

  useToolbarEvent<KeyboardEvent>(
    'keydown',
    zoomOutEvent,
    isZoomOut,
    isZoomEnabled && zoomOutEnabled,
    overlayRef?.current as HTMLDivElement,
  );

  useToolbarEvent<WheelEvent>(
    'wheel',
    () => handleZoom('zoom-out', true),
    isZoomOutWheel,
    isZoomEnabled && zoomOutEnabled,
    overlayRef?.current as HTMLDivElement,
  );

  return isZoomEnabled ? (
    <>
      <ChartToolbarRenderer.Control
        ref={zoomInButtonRef}
        prefixIcon={<ZoomInIcon />}
        tooltipText={intl.formatMessage(HISTOGRAM_MESSAGES.zoomIn)}
        tooltipKeyShortcut={getKeyShortcutByAgent(
          `+${intl.formatMessage(HISTOGRAM_MESSAGES.zoomActionArrowUp)}`,
        )}
        onKeyDown={(event) => handleZoomKeyboardMode(event, 'zoom-in')}
        onClick={() => handleZoom('zoom-in')}
        tabIndex={tabIndexIn}
        disabled={!zoomInEnabled}
      />
      <ChartToolbarRenderer.Control
        ref={zoomOutButtonRef}
        prefixIcon={<ZoomOutIcon />}
        tooltipText={intl.formatMessage(HISTOGRAM_MESSAGES.zoomOut)}
        tooltipKeyShortcut={getKeyShortcutByAgent(
          `+${intl.formatMessage(HISTOGRAM_MESSAGES.zoomActionArrowDown)}`,
        )}
        onKeyDown={(event) => handleZoomKeyboardMode(event, 'zoom-out')}
        onClick={() => handleZoom('zoom-out')}
        tabIndex={tabIndexOut}
        disabled={!zoomOutEnabled}
      />
    </>
  ) : null;
};

ZoomInOutButtons['displayName'] = 'ZoomInOutButtons';
